class Solution:
    def validArrangement(self, pairs: List[List[int]]) -> List[List[int]]:
        graph = defaultdict(list)
        degree = defaultdict(int)
        for x, y in pairs:
            graph[x].append(y)
            degree[x] += 1
            degree[y] -= 1

        start = pairs[0][0]
        for k in degree:
            if degree[k] == 1:
                start = k
                break

        ans = deque()
        def dfs(u):
            while graph[u]:
                v = graph[u].pop()
                dfs(v)
            ans.appendleft(u)

        dfs(start)
        result = []
        for i in range(len(ans)-1):
            result.append([ans[i], ans[i+1]])
