class Solution:
    def numPermsDISequence(self, s: str) -> int:
        mod = 10**9 + 7
        n = len(s)
        mem = {}
        def dfs(i, val):
            if i == n:
                return 1
            if (i, val) in mem:
                return mem[(i, val)]
            p = 0
            if s[i] == "D":
                for ind in range(0, val):
                    p = (p + dfs(i + 1, ind)) % mod
            else:
                for ind in range(val + 1, n - i + 1):
                    p = (p + dfs(i + 1, ind)) % mod
            mem[(i, val)] = p
            return p
        total = 0
        for first in range(n + 1):
            total = (total + dfs(0, first)) % mod
        return total

