class Solution:
    def numPermsDISequence(self, s: str) -> int:
        from collections import defaultdict
        mem = defaultdict(int)
        MOD = 10**9 + 7
        n = len(s)
        def dfs(i, val):
            if i == n:
                return 1
            if (i, val) in mem:
                return mem[(i, val)]
            p = 0
            if s[i] == "D":
                for ind in range(0, val):
                    p = (p + dfs(i + 1, ind)) % MOD
            else:
                for ind in range(val + 1, n + 1):
                    p = (p + dfs(i + 1, ind)) % MOD
            mem[(i, val)] = p
            return p
        return sum(dfs(0, v) for v in range(n + 1)) % MOD

