class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        from functools import lru_cache

        rows = len(pizza)
        cols = len(pizza[0])

        apples = [[0] * (cols + 1) for _ in range(rows + 1)]
        for r in range(rows - 1, -1, -1):
            for c in range(cols - 1, -1, -1):
                apples[r][c] = apples[r + 1][c] + apples[r][c + 1] - apples[r + 1][c + 1] + (pizza[r][c] == 'A')

        @lru_cache(None)
        def dp(r, c, cuts_left):
            if apples[r][c] == 0:
                return 0
            if cuts_left == 0:
                return 1

            total = 0
            for nr in range(r + 1, rows):
                if apples[r][c] - apples[nr][c] > 0:
                    total += dp(nr, c, cuts_left - 1)

            for nc in range(c + 1, cols):
                if apples[r][c] - apples[r][nc] > 0:
                    total += dp(r, nc, cuts_left - 1)

            return total % 1000000007

        return dp(0, 0, k - 1) % 1000000007

