class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not set(s2).issubset(set(s1)): 
            return 0

        rec, track = [0], {}
        ct = start = 0

        while True:
            for char in s2:
                pos = s1.find(char, start)
                if pos == -1:
                    ct += 1
                    pos = s1.find(char)
                start = pos + 1

            rec.append(ct + 1)

            if rec[-1] > n1: 
                return (len(rec) - 2) // n2

            if start in track:
                break
            track[start] = len(rec) - 1

        cycle_start = rec[track[start]]
        cycle_len = len(rec) - 1 - track[start]
        cycle_reps = ct + 1 - cycle_start
        remain = n1 - cycle_start

        cycles = remain // cycle_reps
        rem_reps = remain % cycle_reps

        ptr2 = 0
        while rec[ptr2] <= cycle_start + rem_reps: 
            ptr2 += 1

        return (cycle_start + cycles * cycle_len + ptr2 - 1) // n2

