class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:

        rec, track = [0], {}
        ct = start = 0

        if not set(s2).issubset(set(s1)):
            return 0

        s1_filtered = ''.join(char for char in s1 if char in set(s2))

        while True:
            for char in s2:
                ptr = s1_filtered.find(char, start)
                if ptr == -1:
                    ct += 1
                    ptr = s1_filtered.find(char)
                    if ptr == -1:
                        return 0
                start = ptr + 1
            rec.append(ct + 1)

            if rec[-1] >= n1:
                return (len(rec) - 2) // n2

            if start not in track:
                track[start] = len(rec) - 1
            else:
                break

        cycle_start_idx = track[start]
        cycle_start_val = rec[cycle_start_idx]
        cycle_len_val = rec[-1] - cycle_start_val
        cycle_len_idx = len(rec) - 1 - cycle_start_idx

        rest_n1 = n1 - cycle_start_val
        full_cycles = rest_n1 // cycle_len_val
        rem_n1 = cycle_start_val + rest_n1 % cycle_len_val

        i = 0
        while i < len(rec) and rec[i] <= rem_n1:
            i += 1
        matches_in_rem = i - 1

        total_matches = cycle_start_idx + full_cycles * cycle_len_idx + matches_in_rem
        return total_matches // n2

