class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not set(s2).issubset(set(s1)): 
            return 0

        rec, track = [0], {}
        ct = start = 0

        while True:
            for char in s2:
                ptr = s1.find(char, start)
                if ptr == -1:
                    ct += 1
                    ptr = s1.find(char)
                    if ptr == -1:
                        return 0
                start = ptr + 1
            rec.append(ct + 1)

            if rec[-1] >= n1: 
                return (len(rec) - 2) // n2

            if start not in track: 
                track[start] = len(rec) - 1
            else: 
                break

        cycle_start = rec[track[start]]
        cycle_len = len(rec) - 1 - track[start]
        cycle_rep = ct + 1 - cycle_start
        rest = n1 - cycle_start

        rem = cycle_start + rest % cycle_rep
        ptr2 = 0
        while rec[ptr2] <= rem: 
            ptr2 += 1

        return (cycle_len * (rest // cycle_rep) + ptr2 - 1) // n2

