        for i in range(self.r):
            for j in range(self.c):
                self.pref[i + 1][j + 1] = (self.pref[i + 1][j] + self.pref[i][j + 1] 
                                            - self.pref[i][j] + (pizza[i][j] == 'A'))

        @lru_cache(None)
        def dp(i, j, cuts):
            if cuts == 0:
                return 1 if self.pref[self.r][self.c] - self.pref[i][self.c] - self.pref[self.r][j] + self.pref[i][j] > 0 else 0

            res = 0
            for ni in range(i + 1, self.r):
                if self.pref[ni][self.c] - self.pref[i][self.c] - self.pref[ni][j] + self.pref[i][j] > 0:
