            last_pos = start - 1
            if rec[-1] > n1:
                return (cur_len - 1) // n2
            if last_pos in track:
                cycle_start_idx = track[last_pos]
                cycle_len = cur_len - cycle_start_idx
                cycle_s1_count = rec[-1] - rec[cycle_start_idx]
                prefix_len = cycle_start_idx
