class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not set(s2).issubset(set(s1)):
            return 0
        rec, track = [0], {}
        ct = start = ptr = 0
        while True:
            for char in s2:
                idx = s1.find(char, start)
                if idx == -1:
                    ct += 1
                    idx = s1.find(char)
                    if idx == -1:
                        return 0
                start = idx + 1
            rec.append(ct + 1)
            if rec[-1] > n1:
                return (len(rec) - 2) // n2
            if ptr not in track:
                track[ptr] = len(rec) - 1
            else:
                break
            ptr = start % len(s1)
        cycle_start = rec[track[ptr]]
        cycle1 = ct + 1 - cycle_start
        cycle2 = len(rec) - 1 - track[ptr]
        rest = n1 - cycle_start
        ptr2 = 0
        while rec[ptr2] <= rest:
            ptr2 += 1
        return (cycle2 * (rest // cycle1) + ptr2 - 1) // n2

